\label{prop:residualgluing}
Let $s\geq3$, $L=H_1(\mathcal X_s;\mathbb Z)$, and $p\ne3$ be a prime dividing $s$.
Put $r=s/p$ and $P=\langle T^{3r}\rangle$.
As a module for the labeled residual group $D_{3s}/P\cong D_{3r}$,
\begin{equation}\label{eq:residualgluing}
 \mathcal G_P(L)\cong\mathbb F_p[t]/(1+t^r+t^{2r}),\qquad
 T v(t)=tv(t),\quad Rv(t)=t^{-1}v(t^{-1}).
\end{equation}
Translation has exact order $3r$ on this quotient.
For the order-three subgroup, $\mathcal G_{P_3}(L)\cong\mathbb F_3$ has $T=1$ and $R=-1$.

\label{lem:p683collapse}
Each $B_i$ is contained in the unique tetrahedron $Q_i$.  Hence the thirteen
pairs $(B_i,Q_i)$ form a cyclic orbit of elementary collapses.

\label{thm:cyclic-action}
Under cyclic translation,
\begin{align*}
 \widetilde H_2(\operatorname{Ind}(G(13,2));\mathbb Z)
   &\cong \operatorname{Aug}_{\mathbb Z}(C_{13}),\\
 T_*\mid \widetilde H_3(\operatorname{Ind}(G(14,4));\mathbb Z)&=+1,\\
 T_*\mid \widetilde H_2(\operatorname{Ind}(G(14,5));\mathbb Z)&=-1.
\end{align*}
In particular, the two fourteen-vertex spheres carry different orientation
characters under the same cyclic generator.

\label{lem:homologywedge}
Let $X$ be a simply connected CW complex with reduced integral homology concentrated in degree $q\ge2$ and equal to $\mathbb Z^r$ there.
Then $X\simeq\bigvee^r S^q$.

\label{prop:chainchecks}
For each of the four specified complexes, $\partial z_j=0$, $Pz_j=e_j$, and $P$ kills the boundary of every $(q+1)$-simplex.
The full domains checked are
