\label{lem:gluing}
Let $a,b\in\mathbb Z[t]$ be monic and coprime over $\mathbb Q[t]$, and put $L=\mathbb Z[t]/(ab)$.
Then $A=\ker(a:L\to L)=bL$, $D=\ker(b:L\to L)=aL$, $A\cap D=0$, and
\begin{equation}\label{eq:quotient}
 L/(A\oplus D)\cong\mathbb Z[t]/(a,b).
\end{equation}
There is an exact sequence of $\mathbb Z[t]$-modules
\begin{equation}\label{eq:extension}
 0\longrightarrow\mathbb Z[t]/(b)\xrightarrow{\ \overline g\mapsto ag\ }L
 \longrightarrow\mathbb Z[t]/(a)\longrightarrow0.
\end{equation}
It splits if and only if $(a,b)=\mathbb Z[t]$.

\label{prop:tilingdihedral}
For the modules $H,L$ of Proposition~\ref{prop:tilingindex}, there is an
isomorphism of integral $D_{22}$ modules with specified submodule
\begin{equation}\label{eq:tilingdihedralpair}
 (H,L)\cong(A\oplus P,\ker\epsilon_2\oplus P),
 \qquad R(p(t))=-tp(t^{-1})\text{ on both factors}.
\end{equation}
